local HempRetter = {}
local PRODUCTS = {
    retted_hemp = { name = "Razmočena konoplja", hempStalkCost = 2, waterCost = 2, time = 2, cost = 12, quality = 30, description = "Razmočena konoplja za ločevanje vlaken." },
    broken_hemp = { name = "Lomljena konoplja", hempStalkCost = 3, waterCost = 2, time = 3, cost = 32, quality = 50, prestige = 1, description = "Lomljena konoplja za vrvi." },
    scutched_hemp = { name = "Tolčena konoplja", hempStalkCost = 3, waterCost = 2, time = 5, cost = 75, quality = 65, prestige = 2, happiness = 1, description = "Tolčena konoplja za predenje." },
    hackled_hemp = { name = "Česana konoplja", hempStalkCost = 4, waterCost = 2, oilCost = 1, time = 7, cost = 180, quality = 80, prestige = 5, happiness = 2, description = "Česana konoplja za fine niti." },
    silver_tow_hemp = { name = "Srebrni kuclji konoplja", hempStalkCost = 5, silverCost = 1, waterCost = 2, oilCost = 1, time = 10, cost = 420, quality = 92, prestige = 11, happiness = 3, description = "Konoplja s srebrnimi kuclji za plemiče." },
    royal_grand_hemp = { name = "Kraljevski veliki konoplja", hempStalkCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, waterCost = 3, oilCost = 1, time = 15, cost = 1400, quality = 100, prestige = 33, happiness = 8, description = "Velika kraljevska konoplja z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Konopljarska delavnica", cost = { gold = 260, wood = 130, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    retting_pond = { name = "Močilnik", cost = { gold = 850, wood = 250, stone = 350, water = 10 }, upkeep = 20, qualityBonus = 18 },
    breaking_house = { name = "Lomilnica", cost = { gold = 2100, wood = 350, stone = 600, silver = 30, hemp = 8 }, upkeep = 52, qualityBonus = 30 },
    royal_hemp_atelier = { name = "Kraljevski atelje konoplje", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
HempRetter.hempStalkStock = 22; HempRetter.waterStock = 18; HempRetter.oilStock = 12; HempRetter.silverStock = 8; HempRetter.goldStock = 6; HempRetter.jewelStock = 6
HempRetter.productStock = {}; HempRetter.buildings = {}; HempRetter.maker = nil; HempRetter.activeMaking = {}; HempRetter.totalProducts = 0; HempRetter.dayTimer = 0
function HempRetter.init() HempRetter.hempStalkStock=22; HempRetter.waterStock=18; HempRetter.oilStock=12; HempRetter.silverStock=8; HempRetter.goldStock=6; HempRetter.jewelStock=6; HempRetter.productStock={}; HempRetter.buildings={}; HempRetter.maker=nil; HempRetter.activeMaking={}; HempRetter.totalProducts=0; HempRetter.dayTimer=0; print("[HempRetter] Royal Hemp Retter System initialized (6 products, 4 buildings)") end
function HempRetter.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HempRetter.maker={name=n or ("Konopljarc "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Konopljarc najet: %s (spretnost: %d)",HempRetter.maker.name,s),"success") end; return true end
function HempRetter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HempRetter.build(id) local ok,e=HempRetter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HempRetter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HempRetter.getQualityBonus() local b=0; for _,bd in ipairs(HempRetter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HempRetter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.hempStalkCost and HempRetter.hempStalkStock<(d.hempStalkCost or 0) then return false,"Premalo konopljin stebel" end; if d.waterCost and HempRetter.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.oilCost and HempRetter.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.silverCost and HempRetter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HempRetter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HempRetter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #HempRetter.buildings==0 then return false,"Potrebna delavnica" end; if not HempRetter.maker then return false,"Potreben konopljarc" end; return true end
function HempRetter.make(pt,qty) qty=qty or 5; local ok,e=HempRetter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.hempStalkCost then HempRetter.hempStalkStock=HempRetter.hempStalkStock-d.hempStalkCost*qty end; if d.waterCost then HempRetter.waterStock=HempRetter.waterStock-d.waterCost*qty end; if d.oilCost then HempRetter.oilStock=HempRetter.oilStock-d.oilCost*qty end; if d.silverCost then HempRetter.silverStock=HempRetter.silverStock-d.silverCost*qty end; if d.goldCost then HempRetter.goldStock=HempRetter.goldStock-d.goldCost*qty end; if d.jewelCost then HempRetter.jewelStock=HempRetter.jewelStock-d.jewelCost*qty end; local t=d.time; if HempRetter.maker then t=math.max(1,t-math.floor(HempRetter.maker.skill/12)) end; table.insert(HempRetter.activeMaking,{id="hemp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HempRetter.completeMaking(m) local q=1.0+(HempRetter.getQualityBonus()/100); if HempRetter.maker then q=q+(HempRetter.maker.skill/180) end; q=math.min(2.0,q); HempRetter.productStock[m.productType]=(HempRetter.productStock[m.productType] or 0)+m.quantity; HempRetter.totalProducts=HempRetter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HempRetter.maker then HempRetter.maker.itemsMade=HempRetter.maker.itemsMade+m.quantity; if math.random()<0.20 then HempRetter.maker.skill=math.min(100,HempRetter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Konoplja izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hemp.completed",{productName=m.productName,quality=m.quality}) end end
function HempRetter.update(dt) if not _G.state then return end; HempRetter.dayTimer=HempRetter.dayTimer+dt; if HempRetter.dayTimer>=30 then HempRetter.dayTimer=0; for i=#HempRetter.activeMaking,1,-1 do local m=HempRetter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HempRetter.completeMaking(m); table.remove(HempRetter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HempRetter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HempRetter.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HempRetter.getStats() return {hempStalkStock=HempRetter.hempStalkStock,waterStock=HempRetter.waterStock,oilStock=HempRetter.oilStock,silverStock=HempRetter.silverStock,goldStock=HempRetter.goldStock,jewelStock=HempRetter.jewelStock,productStock=HempRetter.productStock,numBuildings=#HempRetter.buildings,hasMaker=HempRetter.maker~=nil,makerName=HempRetter.maker and HempRetter.maker.name or "—",makerSkill=HempRetter.maker and HempRetter.maker.skill or 0,activeMaking=#HempRetter.activeMaking,totalProducts=HempRetter.totalProducts} end
return HempRetter
